    PartyFrameHeader:SetWidth(PartyScreenPanel:GetWidth())
    local button = APR.UI:IconButton(PartyFrameHeader, "send", 22, --[[APR_DIAG]]APRTrace("APR-Core/features/group/PathSharingUI.lua:70:callback#8", --[[/APR_DIAG]]function()
        Sharing:SharePath()
    end--[[APR_DIAG]])--[[/APR_DIAG]])
    button:SetPoint("RIGHT", PartyFrameHeader.MinimizeButton, "LEFT", -6, 0)
    button:SetHeight(22)
    APR.UI:Tooltip(button, L["GROUP_PATH_SHARE_ACTION"])
    PartyFrameHeader.SharePathButton = button
    if PartyFrameHeader.Text then
        PartyFrameHeader.Text:ClearAllPoints()
        PartyFrameHeader.Text:SetPoint("LEFT", 6, 0)
        PartyFrameHeader.Text:SetPoint("RIGHT", button, "LEFT", -6, 0)
    end
